window.__votdWeek && window.__votdWeek({"week":"2027-11-15","reading":"1 and 2 Peter","days":[{"d":"2027-11-15","ref":"1 Peter 1:11","b":"1 Peter","c":1,"v":11,"he":"לַחְקֹר לָדַעַת מַה־זּוּ וְאֵי־זוּ הָעֵת אֲשֶׁר הוֹדִיעָהּ רוּחַ הַמָּשִׁיחַ אֲשֶׁר בְּקִרְבָּם בְּהַגִּידוֹ מֵרֹאשׁ אֵת־עִנּוּיֵי הַמָּשִׁיחַ וְאֶת־הַגְּדֻלּוֹת אֲשֶׁר אַחֲרֵיהֶם׃","en":"Searching what, or what manner of time the Spirit of Christ which was in them did signify, when it testified beforehand the sufferings of Christ, and the glory that should follow."},{"d":"2027-11-16","ref":"1 Peter 4:6","b":"1 Peter","c":4,"v":6,"he":"כִּי עַל־כֵּן הִתְבַּשְׂרוּ גַּם־הַמֵּתִים לְמַעַן יִדּוֹנוּ בַבָּשָׂר כִּבְנֵי־אָדָם וְיִחְיוּ בָּרוּחַ כְּדֶרֶךְ אֱלֹהִים׃","en":"For for this cause was the gospel preached also to them that are dead, that they might be judged according to men in the flesh, but live according to God in the spirit."},{"d":"2027-11-17","ref":"2 Peter 1:19","b":"2 Peter","c":1,"v":19,"he":"וּדְבַר הַנְּבוּאָה יוֹתֵר קַיָּם אִתָּנוּ וַהֲטִיבֹתֶם עֲשׂוֹת אֲשֶׁר שַׁתֶּם לִבְּכֶם אֵלָיו כְּנֵר מֵאִיר בִּמְקוֹם אֹפֶל עַד־כִּי יִבָּקַע אוֹר הַיּוֹם וְזָרַח כּוֹכַב הַנֹּגַהּ בִּלְבַבְכֶם׃","en":"We have also a more sure word of prophecy; whereunto ye do well that ye take heed, as unto a light that shineth in a dark place, until the day dawn, and the day star arise in your hearts:"},{"d":"2027-11-18","ref":"2 Peter 1:21","b":"2 Peter","c":1,"v":21,"he":"כִּי מֵעוֹלָם לֹא־יָצְאָה נְבוּאָה בִּרְצוֹן הָאָדָם כִּי אַנְשֵׁי אֱלֹהִים הַקְּדוֹשִׁים דִּבְּרוּ כַּאֲשֶׁר נְשָׂאָם רוּחַ־הַקֹּדֶשׁ׃","en":"For the prophecy came not in old time by the will of man: but holy men of God spake as they were moved by the Holy Ghost."},{"d":"2027-11-19","ref":"2 Peter 2:20","b":"2 Peter","c":2,"v":20,"he":"כִּי אַחֲרֵי הִמָּלְטָם מִטֻּמְאֹת הָעוֹלָם בְּדַעַת אֲדֹנֵינוּ וּמוֹשִׁיעֵנוּ יֵשׁוּעַ הַמָּשִׁיחַ אִם־שָׁבוּ וְהָטְבְּעוּ בְתוֹכָן וְנִכְבָּשׁוּ אַחֲרִיתָם תִּהְיֶה רָעָה מֵרֵאשִׁיתָם׃","en":"For if after they have escaped the pollutions of the world through the knowledge of the Lord and Saviour Jesus Christ, they are again entangled therein, and overcome, the latter end is worse with them than the beginning."},{"d":"2027-11-20","ref":"2 Peter 3:10","b":"2 Peter","c":3,"v":10,"he":"בֹּא יָבֹא יוֹם־יְהוָֹה כְּגַנָּב בַּלָּיְלָה אָז הַשָּׁמַיִם בְּשָׁאוֹן יַחֲלֹפוּ וְהַיְסֹדוֹת יְבֹעֲרוּ וְהִתְמֹגֲגוּ וְהָאָרֶץ וְהַמַּעֲשִׂים אֲשֶׁר עָלֶיהָ יִשָּׂרֵפוּ׃","en":"But the day of the Lord will come as a thief in the night; in the which the heavens shall pass away with a great noise, and the elements shall melt with fervent heat, the earth also and the works that are therein shall be burned up."},{"d":"2027-11-21","ref":"2 Peter 3:12","b":"2 Peter","c":3,"v":12,"he":"וּלְחַכּוֹת לְיוֹם־יְהוָֹה שֶׁיָּבֹא וּלְהָחִישׁ אֹתוֹ אֲשֶׁר בּוֹ הַשָּׁמַיִם יָמוּגוּ בָאֵשׁ וְהַיְסֹדוֹת יְבֹעֲרוּ וְנָמַסּוּ׃","en":"Looking for and hasting unto the coming of the day of God, wherein the heavens being on fire shall be dissolved, and the elements shall melt with fervent heat?"}]});
